    // 顔文字パネルの分類カテゴリーの表示順(意図した並び。気分・場面のまとまり順)。
    // キーボードのカテゴリーバーと設定アプリの選択肢は必ずこの順に揃える
    // (設定側は別ターゲットのため App/SettingsModels.swift KaomojiCategoryChoice がこれを写す。
    // 以前は写し元を importedCategoryOrder(辞書の反復順で意図のない並び)にしていたため、
    // 導入時(2026-06-15)からキーボードと設定で並びが食い違っていた。2026-09-02 是正)。
    // 名称が importedEntriesByCategory に無いものは無視され、載っていない分類は末尾に回る。
    // キーは仏語タイトル由来の識別子(rire/kawaii/…)。表示名は KaomojiCategory.title 側。
    static let displayCategoryOrder: [String] = [
        "rire", "kawaii", "timide", "panique", "decu", "triste", "colere", "surprise", "dodo",
        "coucou", "amour", "excite", "action", "bizarre", "heros", "special", "lignes"
    ]

